var t=`0748-bariis-iskukaris`;var n=`world-0748`;var o=`SO`;var a=`eastern-africa`;var s=4;var r=52;var u={en:`Bariis Iskukaris`,ua:`Баріс іскуканіс`};var g={en:`Bariis Iskukaris is a Somalia classic prepared with yellow onion, garlic, ginger root, basmati rice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Баріс іскуканіс, страва кухні країни Сомалі зі складниками: жовта цибуля, часник, корінь імбиру, рис басматі. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,190,`g`],[`garlic`,4,`clove`],[`ginger-root`,20,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Coat the rice in the warm fat with the aromatics and toast gently for about 5 minutes without browning.`,ua:`Змішайте рис із теплим жиром та ароматичними складниками й прогрівайте приблизно 5 хвилин, не підрум’янюючи.`,t:[`sauteing`,`risotto-method`],m:5,i:[[`basmati-rice`,400,`g`],[`ceylon-cinnamon`,1,`pcs`],[`cardamom-pods`,5,`pcs`],[`ground-cloves`,4,`pcs`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 26 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 26 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:26,i:[[`chicken-stock`,700,`ml`],[`ground-cumin`,5,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 8 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 8 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`raisin`,85,`g`]]}];var c={slug:t,id:n,country:`SO`,region:a,servings:4,minutes:52,title:u,text:g,steps:l};export{o as country,c as default,n as id,r as minutes,a as region,s as servings,t as slug,l as steps,g as text,u as title};